input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the catalogue and buys books online."
        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse the catalogue, place orders, and pay for books." {
            webStore = container "Web Store" "The web application customers use to browse the catalogue and place orders." "Spring Boot"
            orderProcessor = container "Order Processor" "Processes and confirms customer orders." "Java"

            customer -> webStore "Browses the catalogue and places orders through" "HTTPS/HTML"
            webStore -> orderProcessor "Submits new orders to" "HTTP/JSON"
        }
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Bookshop system and the Customer who uses it." {
            include *
            autoLayout
        }
        updateViews
    }

    configuration {
        scope softwaresystem
    }
}

